{"currentConversationId":"d1ea38f4-2888-4521-82ae-6388a1c55611","conversations":{"459360f3-6010-4e05-8925-69a129632ecd":{"id":"459360f3-6010-4e05-8925-69a129632ecd","createdAtIso":"2025-08-02T08:49:32.392Z","lastInteractedAtIso":"2025-08-02T09:30:01.167Z","chatHistory":[{"status":"success","request_id":"d541d8cf-99f5-45e5-87f2-a8e543b8f34c","request_message":"apply plugin: 'java'

import org.gradle.internal.os.OperatingSystem

def androidJar = "${System.getenv('ANDROID_HOME')}/platforms/android-35/android.jar"
def buildToolsDir = "${System.getenv('ANDROID_HOME')}/build-tools/35.0.0"
def d8 = "${buildToolsDir}/d8"

// Windows 特殊处理（加 .bat）
if (OperatingSystem.current().isWindows()) {
 d8 += ".bat"
}

java {
 sourceCompatibility = JavaVersion.VERSION_1_8
 targetCompatibility = JavaVersion.VERSION_1_8
}

dependencies {
 compileOnly files(androidJar)
 testImplementation 'junit:junit:4.13.2'
}

// 构建可执行jar
jar {
 archiveFileName = 'screenshot-service.jar'
 manifest {
 attributes(
 'Main-Class': 'com.screenshot.ScreenshotService'
 )
 }
 duplicatesStrategy = DuplicatesStrategy.EXCLUDE
}

// 创建buildExecutableJar任务作为jar任务的别名
task buildExecutableJar {
 dependsOn jar
 doLast {
 println "Executable jar built: ${jar.archiveFile.get()}"
 }
}


task buildDex(type: Exec) {
 dependsOn jar
 group = "build"
 description = "Convert jar to dex using d8"

 def dexOut = layout.buildDirectory.dir("dex").get().asFile

 doFirst {
 file(dexOut).mkdirs()
 }
 commandLine d8,
 "--lib", androidJar,
 "--min-api", "21",
 "--output", dexOut.absolutePath,
 jar.archiveFile.get().asFile.absolutePath
}

task buildDexJar {
 dependsOn buildDex
}

