```bash
# 启动服务
start_service() {
 log_info "启动Socket服务 (端口: $SOCKET_PORT)..."

 # 清理日志
 adb shell "rm -f $LOG_FILE" 2>/dev/null || true

 # 检查dex文件
 log_info "检查dex文件..."
 adb shell "ls -la $DEVICE_PATH/$SERVICE_DEX"

 # 尝试启动服务（前台运行以便看到错误）
 log_info "尝试前台启动服务..."
 adb shell "CLASSPATH=$DEVICE_PATH/$SERVICE_DEX app_process /system/bin $SERVICE_CLASS --port $SOCKET_PORT --debug" || {
 log_error "前台启动失败，查看系统日志..."
 adb logcat -d | tail -20
 return 1
 }
}
```
</augment_code_snippet>

**5. 检查Android版本兼容性：**
```bash
adb shell "getprop ro.build.version.sdk"
```

