 1	#!/bin/bash
 2	
 3	# Screenshot Service 快速部署脚本
 4	# 一键编译、部署、启动
 5	
 6	set -e
 7	
 8	# 配置
 9	DEVICE_PATH="/data/local/tmp"
 10	SERVICE_DEX="k-server.dex"
 11	SERVICE_CLASS="com.github.kirer.adb.Launcher"
 12	TEST_CLASS="com.github.kirer.adb.test.SocketClient"
 13	SOCKET_PORT=8888
 14	LOG_FILE="/sdcard/screenshot_service.log"
 15	
 16	# 颜色输出
 17	GREEN='\033[0;32m'
 18	RED='\033[0;31m'
 19	YELLOW='\033[1;33m'
 20	NC='\033[0m'
 21	
 22	log_info() {
 23	 echo -e "${GREEN}[INFO]${NC} $1"
 24	}
 25	
 26	log_error() {
 27	 echo -e "${RED}[ERROR]${NC} $1"
 28	}
 29	
 30	log_warn() {
 31	 echo -e "${YELLOW}[WARN]${NC} $1"
 32	}
 33	
 34	# 检查设备连接
 35	check_device() {
 36	 if ! adb devices | grep -q "device$"; then
 37	 log_error "没有检测到Android设备连接"
 38	 exit 1
 39	 fi
 40	}
 41	
 42	# 停止现有服务
 43	stop_existing_service() {
 44	 log_info "停止现有服务..."
 45	
 46	 # 通过端口查找并杀死进程
 47	 local pids=$(adb shell "netstat -tulpn 2>/dev/null | grep ':$SOCKET_PORT ' | awk '{print \$7}' | cut -d'/' -f1" 2>/dev/null || true)
 48	 for pid in $pids; do
 49	 if [ -n "$pid" ] && [ "$pid" != "-" ]; then
 50	 log_info "杀死进程: $pid"
 51	 adb shell "kill $pid" 2>/dev/null || true
 52	 fi
 53	 done
 54	 
 55	 # 等待端口释放
 56	 sleep 2
 57	}
 58	
 59	# 编译DEX
 60	build_dex() {
 61	 log_info "编译DEX文件..."
 62	 if ./gradlew :server-adb-shell:buildDex; then
 63	 log_info "编译成功"
 64	 else
 65	 log_error "编译失败"
 66	 exit 1
 67	 fi
 68	}
 69	
 70	# 部署到设备
 71	deploy() {
 72	 log_info "部署到设备..."
 73	 if adb push server-adb-shell/build/dex/classes.dex $DEVICE_PATH/$SERVICE_DEX; then
 74	 log_info "部署成功"
 75	 else
 76	 log_error "部署失败"
 77	 exit 1
 78	 fi
 79	}
 80	
 81	# 启动服务
 82	start_service() {
 83	 log_info "启动Socket服务 (端口: $SOCKET_PORT)..."
 84	 
 85	 # 清理日志
 86	 adb shell "rm -f $LOG_FILE" 2>/dev/null || true
 87	 
 88	 # 启动服务
 89	 adb shell "CLASSPATH=$DEVICE_PATH/$SERVICE_DEX app_process /system/bin $SERVICE_CLASS --port $SOCKET_PORT --debug > $LOG_FILE 2>&1 &"
 90	 
 91	 # 等待启动
 92	 sleep 3
 93	 
 94	 # 测试连接
 95	 log_info "测试服务连接..."
 96	 local response=$(adb shell "CLASSPATH=$DEVICE_PATH/$SERVICE_DEX app_process /system/bin $TEST_CLASS localhost $SOCKET_PORT status" 2>/dev/null || echo "ERROR")
 97	 
 98	 if [[ "$response" == *"OK"* ]]; then
 99	 log_info "✅ 服务启动成功！"
 100	 log_info "响应: $response"
 101	 else
 102	 log_error "❌ 服务启动失败"
 103	 log_info "查看日志:"
 104	 adb shell "cat $LOG_FILE 2>/dev/null || echo '无日志文件'"
 105	 exit 1
 106	 fi
 107	}
 108	
 109	# 显示使用说明
 110	show_usage() {
 111	 echo "Screenshot Service 快速部署脚本"
 112	 echo ""
 113	 echo "用法:"
 114	 echo " $0 # 完整部署 (编译+部署+启动)"
 115	 echo " $0 --no-build # 跳过编译 (仅部署+启动)"
 116	 echo " $0 --port 9999 # 使用自定义端口"
 117	 echo " $0 --test # 测试现有服务"
 118	 echo " $0 --stop # 停止服务"
 119	 echo ""
 120	}
 121	
 122	# 测试现有服务
 123	test_service() {
 124	 log_info "测试现有服务..."
 125	 local response=$(adb shell "CLASSPATH=$DEVICE_PATH/$SERVICE_DEX app_process /system/bin com.screenshot.test.SocketClient localhost $SOCKET_PORT status" 2>/dev/null || echo "ERROR")
 126	 
 127	 if [[ "$response" == *"OK"* ]]; then
 128	 log_info "✅ 服务运行正常"
 129	 log_info "响应: $response"
 130	 
 131	 # 测试截图
 132	 log_info "测试截图功能..."
 133	 local screenshot_response=$(adb shell "CLASSPATH=$DEVICE_PATH/$SERVICE_DEX app_process /system/bin com.screenshot.test.SocketClient localhost $SOCKET_PORT 'screenshot /sdcard/test_$(date +%s).png'" 2>/dev/null || echo "ERROR")
 134	 log_info "截图响应: $screenshot_response"
 135	 else
 136	 log_error "❌ 服务未运行或连接失败"
 137	 fi
 138	}
 139	
 140	# 主函数
 141	main() {
 142	 local do_build=true
 143	 local action="deploy"
 144	 
 145	 # 解析参数
 146	 while [[ $# -gt 0 ]]; do
 147	 case $1 in
 148	 --no-build)
 149	 do_build=false
 150	 shift
 151	 ;;
 152	 --port)
 153	 SOCKET_PORT="$2"
 154	 shift 2
 155	 ;;
 156	 --test)
 157	 action="test"
 158	 shift
 159	 ;;
 160	 --stop)
 161	 action="stop"
 162	 shift
 163	 ;;
 164	 --help)
 165	 show_usage
 166	 exit 0
 167	 ;;
 168	 *)
 169	 log_warn "未知选项: $1"
 170	 shift
 171	 ;;
 172	 esac
 173	 done
 174	 
 175	 log_info "=== Screenshot Service 快速部署 ==="
 176	 
 177	 # 检查设备
 178	 check_device
 179	 
 180	 case "$action" in
 181	 "test")
 182	 test_service
 183	 ;;
 184	 "stop")
 185	 stop_existing_service
 186	 log_info "服务已停止"
 187	 ;;
 188	 "deploy")
 189	 # 停止现有服务
 190	 stop_existing_service
 191	 
 192	 # 编译
 193	 if [ "$do_build" = true ]; then
 194	 build_dex
 195	 fi
 196	 
 197	 # 部署
 198	 deploy
 199	 
 200	 # 启动
 201	 start_service
 202	 
 203	 echo ""
 204	 log_info " 部署完成！"
 205	 log_info ""
 206	 log_info "测试命令:"
 207	 echo " ./server-adb-shell/socket_client.sh \"screenshot /sdcard/test.png\""
 208	 echo " ./server-adb-shell/socket_client.sh \"status\""
 209	 echo ""
 210	 log_info "管理命令:"
 211	 echo " $0 --test # 测试服务"
 212	 echo " $0 --stop # 停止服务"
 213	 ;;
 214	 esac
 215	}
 216	
 217	# 执行主函数
 218	main "$@"
