 1	#!/bin/bash
 2	
 3	# Screenshot Service 快速部署脚本
 4	# 一键编译、部署、启动
 5	
 6	set -e
 7	
 8	# 配置
 9	DEVICE_PATH="/data/local/tmp"
 10	SERVICE_DEX="k-server.dex"
 11	SERVICE_CLASS="com.github.kirer.adb.Launcher"
 12	TEST_CLASS="com.github.kirer.adb.test.SocketClient"
 13	SOCKET_PORT=8888
 14	LOG_FILE="/sdcard/screenshot_service.log"
 15	
 16	# 颜色输出
 17	GREEN='\033[0;32m'
 18	RED='\033[0;31m'
 19	YELLOW='\033[1;33m'
 20	NC='\033[0m'
 21	
 22	log_info() {
 23	 echo -e "${GREEN}[INFO]${NC} $1"
 24	}
 25	
 26	log_error() {
 27	 echo -e "${RED}[ERROR]${NC} $1"
 28	}
 29	
 30	log_warn() {
 31	 echo -e "${YELLOW}[WARN]${NC} $1"
 32	}
 33	
 34	# 检查设备连接
 35	check_device() {
 36	 if ! adb devices | grep -q "device$"; then
 37	 log_error "没有检测到Android设备连接"
 38	 exit 1
 39	 fi
 40	}
