 1	package com.github.kirer.adb.screenshot;
 2	
 3	import android.graphics.Bitmap;
 4	
 5	import com.genymobile.scrcpy.util.Ln;
 6	
 7	import java.io.File;
 8	import java.io.FileOutputStream;
 9	import java.io.IOException;
 10	
 11	/**
 12	 * 屏幕截图服务主类
 13	 * 通过adb shell app_process启动，提供持续的屏幕截图服务
 14	 */
 15	public class ScreenshotService {
 16	
 17	 private ScreenCaptureManager captureManager;
 18	 private volatile boolean running = false;
 19	 private volatile boolean initialized = false;
 20	
 21	 public ScreenshotService(ScreenshotConfig config){
 22	 Ln.i("ScreenshotService Initializing...");
 23	 if (initialized) {
 24	 Ln.w("ScreenshotService already initialized");
 25	 return;
 26	 }
 27	 if (config == null) {
 28	 throw new IllegalArgumentException("ScreenshotService Config cannot be null");
 29	 }
 30	 try {
 31	 // 创建屏幕捕获管理器
 32	 captureManager = new ScreenCaptureManager(config);
 33	 // 初始化屏幕捕获管理器
 34	 captureManager.initialize();
 35	 initialized = true;
 36	 Ln.i("ScreenshotService initialized successfully");
 37	 Ln.i("Display: " + captureManager.getDisplayInfo().getSize().getWidth() + "x" + captureManager.getDisplayInfo().getSize().getHeight());
 38	 } catch (Exception e) {
 39	 Ln.e("Failed to initialize ScreenshotService", e);
 40	 cleanup();
 41	 throw new RuntimeException("Service initialization failed", e);
 42	 }
 43	 }
 44	
 45	 /**
 46	 * 启动服务
 47	 */
 48	 public void start() {
 49	 if (!initialized) {
 50	 throw new IllegalStateException("Service not initialized");
 51	 }
 52	 Ln.i("Starting ScreenshotService...");
 53	 try {
 54	 // 启动屏幕捕获
 55	 captureManager.startCapture();
 56	 running = true;
 57	 Ln.i("ScreenshotService started successfully");
 58	 } catch (Exception e) {
 59	 Ln.e("Failed to start ScreenshotService", e);
 60	 throw new RuntimeException("Service start failed", e);
 61	 }
 62	 }
 63	
 64	 /**
 65	 * 获取屏幕截图的公共接口
 66	 */
 67	 public Bitmap takeScreenshot() {
 68	 if (!running || !initialized) {
 69	 Ln.w("Service not running or not initialized");
 70	 return null;
 71	 }
 72	 if (captureManager == null) {
 73	 Ln.e("CaptureManager not available");
 74	 return null;
 75	 }
 76	 try {
 77	 long startTime = System.currentTimeMillis();
 78	 // 使用带重试机制的截图方法
 79	 Bitmap bitmap = captureManager.captureScreen();
 80	 long duration = System.currentTimeMillis() - startTime;
 81	 if (bitmap != null) {
 82	 Ln.d("Screenshot taken in " + duration + "ms, size: " + bitmap.getWidth() + "x" + bitmap.getHeight());
 83	 } else {
 84	 Ln.w("Screenshot failed after " + duration + "ms");
 85	 }
 86	 return bitmap;
 87	 } catch (Exception e) {
 88	 Ln.e("Error taking screenshot", e);
 89	 return null;
 90	 }
 91	 }
 92	 
 93	 /**
 94	 * 保存截图到文件（用于测试和调试）
 95	 */
 96	 public void saveScreenshot(String filePath) {
 97	 Bitmap bitmap = takeScreenshot();
 98	 if (bitmap == null) {
 99	 Ln.e("No bitmap to save");
 100	 return;
 101	 }
 102	 try {
 103	 File file = new File(filePath);
 104	 File parentDir = file.getParentFile();
 105	 if (parentDir != null && !parentDir.exists()) {
 106	 parentDir.mkdirs();
 107	 }
 108	 FileOutputStream fos = new FileOutputStream(file);
 109	 bitmap.compress(Bitmap.CompressFormat.PNG, 100, fos);
 110	 fos.close();
 111	 Ln.i("Screenshot saved to: " + filePath);
 112	 } catch (IOException e) {
 113	 Ln.e("Failed to save screenshot to " + filePath, e);
 114	 } finally {
 115	 // 回收Bitmap
 116	 if (!bitmap.isRecycled()) {
 117	 bitmap.recycle();
 118	 }
 119	 }
 120	 }
 121	
 122	 /**
 123	 * 停止服务
 124	 */
 125	 public void stop() {
 126	 Ln.i("Stopping ScreenshotService...");
 127	 running = false;
 128	 if (captureManager != null) {
 129	 captureManager.stopCapture();
 130	 }
 131	 Ln.i("ScreenshotService stopped");
 132	 }
 133	 
 134	 /**
 135	 * 清理资源
 136	 */
 137	 public void cleanup() {
 138	 Ln.i("Cleaning up service");
 139	 stop();
 140	 if (captureManager != null) {
 141	 captureManager.cleanup();
 142	 }
 143	 initialized = false;
 144	 Ln.i("Service cleanup completed");
 145	 }
 146	 
 147	 /**
 148	 * 检查服务是否正在运行
 149	 */
 150	 public boolean isRunning() {
 151	 return running && initialized;
 152	 }
