 172	 *
 173	 * @throws Exception 启动失败时抛出异常
 174	 */
 175	 public void startCapture() throws Exception {
 176	 Ln.i("Starting screen capture...");
 177	 if (!initialized) {
 178	 throw new IllegalStateException("ScreenCaptureManager not initialized");
 179	 }
 180	 if (capturing) {
 181	 Ln.w("Screen capture already started");
 182	 return;
 183	 }
 184	 try {
 185	 // 创建ImageReader
 186	 int width = displayInfo.getSize().getWidth();
 187	 int height = displayInfo.getSize().getHeight();
 188	 imageReaderHandler.createImageReader(width, height);
 189	 // 创建VirtualDisplay
 190	 createVirtualDisplay();
 191	 capturing = true;
 192	 Ln.i("Screen capture started successfully");
 193	 } catch (Exception e) {
 194	 // 清理失败的资源
 195	 stopCapture();
 196	 throw e;
 197	 }
 198	 }
