 230	 */
 231	 public Bitmap captureScreen() {
 232	 Image image = null;
 233	 try {
 234	 Ln.d("Capturing screen...");
 235	 Bitmap bitmap = null;
 236	 if (imageReaderHandler != null) {
 237	 // 从ImageReader获取最新图像
 238	 image = imageReaderHandler.getLastImage();
 239	 if (image != null) {
 240	 Ln.d("Capturing screen..." + image.getWidth() + "/" + image.getHeight());
 241	 bitmap = BitmapConverter.imageToBitmap(image);
 242	 } else {
 243	 Ln.d("Capturing screen... image is NULL");
 244	 }
 245	 }
 246	 // 处理屏幕旋转
 247	 if (config.isAutoRotate() && displayInfo != null) {
 248	 int rotationAngle = BitmapConverter.getRotationAngle(displayInfo.getRotation());
 249	 if (rotationAngle != 0) {
 250	 Ln.d("Rotating bitmap by " + rotationAngle + " degrees");
 251	 bitmap = BitmapConverter.rotateBitmap(bitmap, rotationAngle);
 252	 }
 253	 }
