 1	package com.github.kirer.adb;
 2	
 3	import android.os.Looper;
 4	
 5	import com.genymobile.scrcpy.util.Ln;
 6	import com.github.kirer.adb.net.CommandProcessor;
 7	import com.github.kirer.adb.net.SocketServer;
 8	import com.github.kirer.adb.screenshot.ScreenshotConfig;
 9	import com.github.kirer.adb.screenshot.ScreenshotService;
 10	import com.github.kirer.adb.commands.ScreenshotCommand;
 11	
 12	public class Launcher {
 13	 private static final String VERSION = "1.0.0";
 14	 private static int socketPort = 8888;
 15	 private static ScreenshotService screenshotService;
 16	
 17	 /**
 18	 * 主入口点，通过app_process调用
 19	 */
 20	 public static void main(String[] args) {
 21	 Ln.i("K Shell ADB Service v" + VERSION + " starting...");
 22	 // 设置未捕获异常处理器
 23	 Thread.setDefaultUncaughtExceptionHandler(new Thread.UncaughtExceptionHandler() {
 24	 @Override
 25	 public void uncaughtException(Thread thread, Throwable exception) {
 26	 Ln.e("Uncaught exception in thread " + thread.getName(), exception);
 27	 System.exit(1);
 28	 }
 29	 });
 30	 try {
 31	 // 准备主循环器
 32	 prepareMainLooper();
 33	 // 解析命令行参数
 34	 ScreenshotConfig config = parseArguments(args);
 35	 // 创建并初始化服务
 36	 screenshotService = new ScreenshotService(config);
 37	 // 启动服务
 38	 screenshotService.start();
 39	 startSocketServer(screenshotService);
 40	 // 运行主循环
 41	 Looper.loop();
 42	 } catch (Exception e) {
 43	 Ln.e("Fatal error during startup", e);
 44	 System.exit(1);
 45	 } finally {
 46	 if (screenshotService != null) {
 47	 screenshotService.cleanup();
 48	 }
 49	 }
 50	 }
 51	
 52	 /**
 53	 * 准备主循环器
 54	 */
 55	 private static void prepareMainLooper() {
 56	 if (Looper.myLooper() == null) {
 57	 Looper.prepare();
 58	 }
 59	 }
 60	
 61	 /**
 62	 * 解析命令行参数
 63	 */
 64	 private static ScreenshotConfig parseArguments(String[] args) {
 65	 ScreenshotConfig config = new ScreenshotConfig();
 66	 for (int i = 0; i < args.length; i++) {
 67	 String arg = args[i];
 68	 try {
 69	 switch (arg) {
 70	 case "--help":
 71	 case "-h":
 72	 printUsage();
 73	 System.exit(0);
 74	 break;
 75	 case "--version":
 76	 case "-v":
 77	 System.out.println("Screenshot Service v" + VERSION);
 78	 System.exit(0);
 79	 break;
 80	 case "--debug":
 81	 Ln.initLogLevel(Ln.Level.DEBUG);
 82	 break;
 83	 case "--port":
 84	 case "-p":
 85	 if (i + 1 < args.length && !args[i + 1].startsWith("-")) {
 86	 socketPort = Integer.parseInt(args[++i]);
 87	 }
 88	 break;
 89	 case "--display-id":
 90	 case "-d":
 91	 if (i + 1 < args.length) {
 92	 config.setDisplayId(Integer.parseInt(args[++i]));
 93	 }
 94	 break;
 95	 case "--max-images":
 96	 case "-m":
 97	 if (i + 1 < args.length) {
 98	 config.setMaxImages(Integer.parseInt(args[++i]));
 99	 }
 100	 break;
 101	 case "--no-auto-rotate":
 102	 config.setAutoRotate(false);
 103	 break;
 104	 default:
 105	 if (arg.startsWith("-")) {
 106	 Ln.w("Unknown argument: " + arg);
 107	 }
 108	 break;
 109	 }
 110	 } catch (NumberFormatException e) {
 111	 Ln.e("Invalid number format for argument " + arg);
 112	 System.exit(1);
 113	 }
 114	 }
 115	 Ln.i("Using config: " + config);
 116	 return config;
 117	 }
 118	
 119	 /**
 120	 * 打印使用说明
 121	 */
 122	 private static void printUsage() {
 123	 System.out.println("Screenshot Service v" + VERSION);
 124	 System.out.println("Usage: CLASSPATH=screenshot-service.jar app_process /system/bin com.screenshot.ScreenshotService [options]");
 125	 System.out.println();
 126	 System.out.println("Options:");
 127	 System.out.println(" -d, --display-id <id> Display ID to capture (default: 0)");
 128	 System.out.println(" -m, --max-images <num> Maximum images in buffer (default: 2)");
 129	 System.out.println(" -s, --socket [port] Enable socket server mode (default port: 8888)");
 130	 System.out.println(" --no-auto-rotate Disable automatic rotation handling");
 131	 System.out.println(" --debug Enable debug logging");
 132	 System.out.println(" -h, --help Show this help message");
 133	 System.out.println(" -v, --version Show version information");
 134	 System.out.println();
 135	 System.out.println("Examples:");
 136	 System.out.println(" # Start socket server on default port 8888");
 137	 System.out.println(" adb shell CLASSPATH=/data/local/tmp/screenshot-service.jar app_process /system/bin com.screenshot.ScreenshotService --socket");
 138	 System.out.println();
 139	 System.out.println(" # Start socket server on custom port");
 140	 System.out.println(" adb shell CLASSPATH=/data/local/tmp/screenshot-service.jar app_process /system/bin com.screenshot.ScreenshotService --socket 9999");
 141	 System.out.println();
 142	 System.out.println("Socket Commands:");
 143	 System.out.println(" screenshot <path> Take screenshot and save to path");
 144	 System.out.println(" status Get service status");
 145	 System.out.println(" help Show available commands");
 146	 }
 147	
 148	 private static void startSocketServer(ScreenshotService screenshotService) {
 149	 try {
 150	 // 创建命令处理器
 151	 CommandProcessor commandProcessor = new CommandProcessor();
 152	 // 注册截图命令
 153	 commandProcessor.registerCommand(new ScreenshotCommand(screenshotService));
 154	 // 创建并启动Socket服务器
 155	 SocketServer socketServer = new SocketServer(socketPort, commandProcessor);
 156	 socketServer.start();
 157	 Ln.i("Socket server started on port " + socketPort);
 158	 } catch (Exception e) {
 159	 Ln.e("Failed to start socket server", e);
 160	 throw new RuntimeException("Socket server start failed", e);
 161	 }
 162	 }
 163	
 164	
 165	}
