 29	 return "ERROR Invalid output path";
 30	 }
 31	 
 32	 // 执行截图
 33	 screenshotService.saveScreenshot(outputPath);
 34	 
 35	 return "OK Screenshot saved to " + outputPath;
 36	 
 37	 } catch (Exception e) {
 38	 Ln.e("Error executing screenshot command", e);
 39	 return "ERROR " + e.getMessage();
 40	 }
