 57	 /**
 58	 * Round both dimensions of this size to be a multiple of 8 (as required by many encoders).
 59	 *
 60	 * @return The current size rounded.
 61	 */
 62	 public Size round8() {
 63	 if (isMultipleOf8()) {
 64	 // Already a multiple of 8
 65	 return this;
 66	 }
 67	
 68	 boolean portrait = height > width;
 69	 int major = portrait ? height : width;
 70	 int minor = portrait ? width : height;
 71	
 72	 major &= ~7; // round down to not exceed the initial size
 73	 minor = (minor + 4) & ~7; // round to the nearest to minimize aspect ratio distortion
 74	 if (minor > major) {
 75	 minor = major;
 76	 }
 77	
 78	 int w = portrait ? minor : major;
 79	 int h = portrait ? major : minor;
 80	 return new Size(w, h);
 81	 }
 82	
 83	 public boolean isMultipleOf8() {
 84	 return (width & 7) == 0 && (height & 7) == 0;
 85	 }
