 1	#!/bin/bash
 2	
 3	# Socket客户端脚本
 4	# 用于向截图服务发送命令
 5	
 6	SOCKET_PORT=8888
 7	
 8	
 9	# 颜色输出
 10	GREEN='\033[0;32m'
 11	RED='\033[0;31m'
 12	NC='\033[0m'
 13	
 14	log_info() {
 15	 echo -e "${GREEN}[INFO]${NC} $1"
 16	}
 17	
 18	log_error() {
 19	 echo -e "${RED}[ERROR]${NC} $1"
 20	}
 21	
 22	# 发送命令
 23	send_command() {
 24	 local command="$1"
 25	 if [ -z "$command" ]; then
 26	 log_error "No command provided"
 27	 return 1
 28	 fi
 29	
 30	 log_info "Sending: $command"
 31	 # 使用我们的Java客户端而不是nc
 32	 local response=$(adb shell "CLASSPATH=/data/local/tmp/screenshot-service.dex app_process /system/bin com.screenshot.test.SocketClient localhost $SOCKET_PORT '$command'" 2>/dev/null)
 33	
 34	 if [ $? -eq 0 ] && [ -n "$response" ]; then
 35	 echo "$response"
 36	 else
 37	 log_error "Failed to send command or no response"
 38	 return 1
 39	 fi
 40	}
 41	
 42	# 使用说明
 43	usage() {
